/usr/bin/bash -lc "node - <<'NODE'
const fs = require('fs');
const plan = JSON.parse(fs.readFileSync('.exp_agent/round_03/plan.json', 'utf8'));
const report = JSON.parse(fs.readFileSync('.exp_agent/round_03/completion.json', 'utf8'));
const schema = JSON.parse(fs.readFileSync('.exp_agent/round_03/completion-schema.json', 'utf8'));
const selected = plan.rules.map(rule => rule.rule);
const errors = [];
if (JSON.stringify(report.selected_rules) "'!== JSON.stringify(selected)) errors.push('"'selected_rules mismatch');
for (const key of ['selected_rules', 'entity_repairs', 'blocked', 'unresolved_external']) if ("'!(key in report)) errors.push('"'missing ' + key);
if ("'!Array.isArray(report.blocked) || report.blocked.length) errors.push('"'blocked not empty');
if ("'!Array.isArray(report.unresolved_external) || report.unresolved_external.length) errors.push('"'unresolved_external not empty');
const required = ['rule','relative_path','locations','entities','evidence','transformation','status'];
if ("'!Array.isArray(report.entity_repairs)) errors.push('"'entity_repairs not array');
for (const [i, entry] of (report.entity_repairs || []).entries()) {
  for (const key of required) if ("'!(key in entry)) errors.push(`entry ${i} missing ${key}`);
  if (entry.status !== '"'repaired') errors.push("'`entry ${i} status`);
  if (!Array.isArray(entry.locations) || !entry.locations.length) errors.push(`entry ${i} locations`);
  if (!Array.isArray(entry.entities) || !entry.entities.length) errors.push(`entry ${i} entities`);
  if (!Array.isArray(entry.evidence) || !entry.evidence.length || entry.evidence.some(v => typeof v !== '"'string' || "'!v.trim())) errors.push(`entry ${i} evidence`);
  if (typeof entry.transformation !== '"'string' || "'!entry.transformation.trim()) errors.push(`entry ${i} transformation`);
}
const planned = [];
for (const rule of plan.rules) for (const file of rule.files) planned.push([rule.rule, file.relative_path, file.locations.map(l => `${l.line}:${l.column}`)]);
const reported = (report.entity_repairs || []).map(e => [e.rule, e.relative_path, e.locations.map(l => `${l.line}:${l.column}`)]);
for (const item of planned) {
  const found = reported.find(r => r[0] === item[0] && r[1] === item[1] && JSON.stringify(r[2]) === JSON.stringify(item[2]));
  if (!found) errors.push('"'missing planned location ' + item.slice(0,2).join(' '));
}
console.log(errors.length ? errors.join('\\n') : 'completion schema and plan coverage checks passed');
process.exitCode = errors.length ? 1 : 0;
NODE"

